const SIZE_PCT = { S: 4.5, M: 7.5, L: 14, XL: 22, XXL: 32 };
const SAMPLE_H_NUMBER = hNumberExampleImage;
const SAMPLE_REMA_OVERVIEW = remaOverviewExampleImage;
